import{C as e,F as t,L as n,Q as r,Y as i,i as a,r as o,v as s,w as c,x as l}from"./main-BW4NsV8y.js";var u={json:{href:`/json/`,label:`JSON Formatter and Validator`},jsondiff:{href:`/jsondiff/`,label:`JSON Diff and Compare`},jsonschema:{href:`/jsonschema/`,label:`JSON Schema Validator`},hash:{href:`/hash/`,label:`Hash and Checksum Calculator`},hexconv:{href:`/hexconv/`,label:`HEX / SREC / BIN Converter`},base64:{href:`/base64/`,label:`Base64 Encoder and Decoder`},aes:{href:`/aes/`,label:`AES-GCM Encryption and Decryption`},serial:{href:`/serial/`,label:`Web Serial Terminal`},jlink:{href:`/jlink/`,label:`Web J-Link Firmware Flasher`},espflash:{href:`/espflash/`,label:`ESP Firmware Flasher`},espbin:{href:`/espbin/`,label:`ESP BIN Firmware Inspector`},imgconv:{href:`/imgconv/`,label:`Image Format Converter`}},d={json:{title:`Online JSON/YAML/XML/CSV/JSONL Formatter and JSONPath Query`,intro:`Make JSON easier to read, check its syntax, convert between JSON, YAML, XML, CSV, TSV, JSONL and Markdown tables, or query the current data with JSONPath. The formatter uses your browser’s parsers and serializers; processing happens locally.`,sections:[{title:`How to Format and Validate JSON`,steps:[`Paste a JSON object or array into the input area, or load the sample.`,`Choose an indentation size and select Format. Use the tree view to inspect nested values.`,`Select Validate to check syntax, or Compress to produce compact JSON.`,`Copy the output after checking the result.`]},{title:`Edit JSON in the Tree`,steps:[`Open the tree view and hover a row to reveal edit, add and delete actions.`,`Select the pencil to edit a primitive value; press Enter to apply or Escape to cancel.`,`Use + on an object or array to add a key or item, and the trash icon to delete.`,`Use Undo and Redo, or Ctrl+Z and Ctrl+Shift+Z, to step through changes.`],paragraphs:[`Edits are written back to the input as formatted JSON, so the tree and text views stay in sync.`,`Adding an object key requires a unique key and a JSON value; invalid JSON values are rejected.`]},{title:`Import YAML as JSON`,steps:[`Paste or import YAML and keep the input format on Auto-detect, or choose YAML explicitly.`,`The page validates the YAML and converts it to a JSON value.`,`Inspect the result in the JSON tree, text or table view, then copy or download it as JSON.`],paragraphs:[`YAML mappings become JSON objects, sequences become arrays, and anchors, aliases and merge keys are resolved. Multiple YAML documents separated by --- are converted into a JSON array and reported as a warning.`,`Binary values, complex non-scalar keys, circular aliases and unsupported tags are rejected instead of being silently converted.`],example:`YAML:
user:
  name: Alice
  tags:
    - admin
    - editor
  active: true

JSON:
{
  "user": {
    "name": "Alice",
    "tags": ["admin", "editor"],
    "active": true
  }
}`},{title:`Import XML as JSON`,steps:[`Paste or import XML and keep the input format on Auto-detect, or choose XML explicitly.`,`Adjust the XML input options if needed: keep the root element, unwrap item arrays, or choose how empty elements are represented.`,`Inspect the JSON result in the tree, text or table view, then copy or download it.`],paragraphs:[`Attributes use the @ prefix, text content uses #text when attributes or child elements are present, and repeated item elements become arrays. The root element is kept by default.`,`XML has no native number or boolean types, so text stays as strings unless type inference is enabled. Mixed content may lose its original order, namespace prefixes are preserved by default, and DOCTYPE declarations are rejected.`],example:`XML:
<user id="42">
  <name>Alice</name>
  <tags>
    <item>admin</item>
    <item>editor</item>
  </tags>
  <note/>
</user>

JSON:
{
  "user": {
    "@id": "42",
    "name": "Alice",
    "tags": ["admin", "editor"],
    "note": null
  }
}`},{title:`Import or export CSV/TSV`,steps:[`Paste or import CSV/TSV and keep Auto-detect, or choose the format explicitly.`,`Choose whether the first row is a header, the delimiter, type inference and empty-cell handling.`,`For JSON to CSV, choose how nested objects and arrays are written, then copy or download the table.`],paragraphs:[`CSV is a flat format. Nested objects and arrays are written as compact JSON by default, or can be flattened with dot-separated column names. Type, null, empty-string and structure differences may be lossy.`,`CSV output guards cells that start with spreadsheet formula characters. Duplicate or empty headers and rows with different lengths are reported as warnings.`,`Use Field mapping to choose, rename and reorder columns, flatten nested paths, join arrays, and set basic type transforms. Mapping applies only to the current conversion and does not modify the input.`],example:`JSON:
[{"name":"Alice","age":30},{"name":"Bob","age":25}]

CSV:
name,age
Alice,30
Bob,25`},{title:`Import or export JSONL`,steps:[`Paste JSONL and keep Auto-detect, or choose JSONL as the input format.`,`Choose whether invalid lines should stop parsing or be skipped with warnings.`,`For JSON to JSONL, arrays are expanded to one compact JSON value per line by default.`],paragraphs:[`JSONL stores one complete JSON value per line. Blank lines are ignored, and a JSON string containing a newline must escape it as \\n so the record stays on one line.`,`Strict mode reports the first invalid line with its line number. Skip mode keeps valid records and lists skipped lines in the input warnings.`],example:`JSON:
[{"id":1},{"id":2}]

JSONL:
{"id":1}
{"id":2}`},{title:`Export JSON as a Markdown Table`,steps:[`Enter or import valid JSON and set the output format to Markdown.`,`Arrays of objects become one table row per object; a plain object becomes a key/value table.`,`Copy or download the generated .md table.`],paragraphs:[`Nested objects and arrays are written as compact JSON inside cells. Pipes are escaped and line breaks become <br> so the table stays valid.`,`A top-level array of primitives becomes a single value column, and an array of arrays becomes numbered columns.`],example:`JSON:
[{"name":"Alice","role":"admin"},{"name":"Bob","role":"editor"}]

Markdown:
| name | role |
| --- | --- |
| Alice | admin |
| Bob | editor |`},{title:`Query JSON with JSONPath`,steps:[`Open the JSONPath Query tab and enter an expression such as $.store.book[?(@.price < 10)].title.`,`Run the query to see matching paths, values, tree, table and text views.`,`Copy the result or export it as JSON or CSV.`],paragraphs:[`The query supports root $, child properties, quoted keys, array indexes, wildcards, slices, recursive descent with .., and filters with @, comparisons and &&/||.`,`Queries run against the current parsed input, so YAML, XML, CSV, TSV or JSONL input is queried as its JSON value. Query results are limited to keep the page responsive.`],example:`Query:
$.store.book[?(@.price < 10)].title

Result:
[
  "Sayings of the Century",
  "Moby Dick"
]`},{title:`Generate TypeScript or JSON Schema`,steps:[`Open the Generate tab with valid parsed input.`,`Choose TypeScript or JSON Schema, set the root name, and decide whether fields should be optional.`,`Copy the generated code or download it as .ts or .json.`],paragraphs:[`TypeScript output creates named interfaces for nested objects. Arrays of objects merge their fields, and fields missing from some items become optional.`,`JSON Schema output uses Draft 2020-12, infers integer/number/string/boolean/null types, writes required fields from the merged structure, and can allow or disallow additional properties.`],example:`JSON:
{"user":{"name":"Alice","tags":["admin"]}}

TypeScript:
export interface User {
  name: string
  tags: string[]
}

export interface Root {
  user: User
}`},{title:`JSON Formatting Example`,paragraphs:[`These compact and indented objects represent the same data:`],example:`Compact:
{"name":"MiniTools","enabled":true,"items":[1,2]}

Indented:
{
  "name": "MiniTools",
  "enabled": true,
  "items": [
    1,
    2
  ]
}`},{title:`Export JSON as YAML`,steps:[`Enter or import valid JSON and choose an indentation size if needed.`,`In the result panel, switch the output format from JSON to YAML.`,`Choose 2 or 4 space indentation, then copy the YAML or download it as a .yaml file.`],paragraphs:[`YAML output preserves keys, values and array order, but it is a different serialization. JSON-only actions such as minifying are disabled while YAML output is selected.`,`Only valid JSON can be exported. If the input has a syntax error, the YAML option is unavailable until the error is fixed.`],example:`JSON:
{"name":"MiniTools","enabled":true,"items":[1,2]}

YAML:
name: MiniTools
enabled: true
items:
  - 1
  - 2`},{title:`Export JSON as XML`,steps:[`Switch the output format from JSON to XML.`,`Set the root element and array item names, choose 2 or 4 space indentation, and decide whether to include the XML declaration.`,`Copy the XML or download it as a .xml file.`],paragraphs:[`Objects become child elements and arrays use repeated item elements. Keys beginning with @ become attributes, and #text supplies element text. Null values become empty elements by default.`,`XML names cannot contain arbitrary characters. Invalid names are sanitized by default and reported as warnings; choose strict mode to stop with an error instead. JSON-only actions such as minifying are disabled in XML mode.`],example:`JSON:
{"user":{"@id":42,"name":"Alice","tags":["admin","editor"]}}

XML:
<?xml version="1.0" encoding="UTF-8"?>
<user id="42">
  <name>Alice</name>
  <tags>
    <item>admin</item>
    <item>editor</item>
  </tags>
</user>`},{title:`Common JSON Errors`,paragraphs:[`JSON requires double quotes around property names and string values. Single quotes, comments, undefined, and trailing commas are not valid JSON. For example, {"count":1,} must become {"count":1}.`,`Syntax validation does not check your application’s required fields, types, or business rules. This tool does not perform JSON Schema validation.`]},{title:`Number Precision and Round-Trip Limits`,paragraphs:[`Numbers are parsed as JavaScript numbers. Integers outside the safe range −9,007,199,254,740,991 to 9,007,199,254,740,991 may lose precision. Store identifiers requiring exact digits as quoted strings before processing.`,`Formatting is not a byte-preserving operation: number notation, escapes and whitespace may change, and duplicate object keys collapse to the last value. Keep the original when exact source text matters. The standalone JSON value null is valid and produces a null result.`]}],faqs:[{question:`What is the difference between formatting and minifying JSON?`,answer:`Formatting adds indentation and line breaks for readability. Minifying removes unnecessary whitespace. Both parse and serialize the input, so the round-trip limitations above apply.`},{question:`Can I convert JSON to YAML here?`,answer:`Yes. Select YAML in the result panel. The tool generates YAML locally from the current JSON value, supports 2 or 4 space indentation, and lets you copy or download the result.`},{question:`Can I convert YAML to JSON here?`,answer:`Yes. Paste YAML and use Auto-detect or select YAML as the input format. YAML mappings become JSON objects, sequences become arrays, and multi-document YAML becomes a JSON array. Binary values, complex keys and circular aliases are rejected.`},{question:`Can I convert XML to JSON here?`,answer:`Yes. Paste XML and use Auto-detect or select XML as the input format. Attributes become @ keys, repeated item elements become arrays, and empty elements become null by default. Mixed content is reported as lossy, and DOCTYPE declarations are rejected.`},{question:`Can I convert between JSON and CSV/TSV?`,answer:`Yes. CSV/TSV can be imported as JSON, and JSON arrays of records can be exported as CSV or TSV. CSV is flat, so nested objects, arrays, types and null/empty-string distinctions may be lossy. Review the CSV warnings before exporting.`},{question:`Can I rename or choose CSV columns?`,answer:`Yes. Open Field mapping in the CSV options to choose source fields, rename output columns, reorder them, flatten nested paths, join arrays, and apply basic type transforms.`},{question:`What is JSONL?`,answer:`JSONL (JSON Lines or NDJSON) stores one complete JSON value per line. It is useful for logs and streaming data. This page can import JSONL as a JSON array and export a JSON array as JSONL.`},{question:`What JSONPath features are supported?`,answer:`The query editor supports root $, dot and bracket child access, array indexes and slices, wildcards, recursive descent, and filters using @, comparison operators and &&/||. Results can be copied or exported as JSON or CSV.`},{question:`Can I generate TypeScript interfaces or JSON Schema?`,answer:`Yes. The Generate tab infers nested TypeScript interfaces or a Draft 2020-12 JSON Schema from the current JSON. You can set the root name, mark all fields optional, and allow additional properties for JSON Schema.`},{question:`Can I convert JSON to XML here?`,answer:`Yes. Select XML in the result panel. You can set the root element, array item name, indentation and XML declaration. JSON objects become elements, arrays use repeated item elements, @ keys become attributes, and #text becomes element text.`},{question:`Does this formatter support JSON comments or trailing commas?`,answer:`No. Remove comments and trailing commas first. JavaScript object literals and JSON5 are not accepted as strict JSON.`},{question:`Can I validate an API response here?`,answer:`Yes, paste its JSON body to check syntax and inspect its structure. A syntax pass does not establish that the response matches an API schema.`},{question:`Is my JSON uploaded?`,answer:`The formatting and validation code runs in your browser and does not send the JSON input to a processing server. The website also loads third-party analytics and advertising scripts.`}],related:[u.base64,u.aes],references:[{href:`https://www.rfc-editor.org/rfc/rfc8259`,label:`RFC 8259: The JSON Data Interchange Format`},{href:`https://www.w3.org/TR/xml/`,label:`W3C Extensible Markup Language (XML) 1.0`}]},jsondiff:{title:`Compare Two JSON Inputs Online`,intro:`Compare two structured inputs by path and review added, removed and changed values. Both sides are parsed locally in your browser, and the inputs can be JSON, YAML, XML, CSV, TSV or JSONL.`,sections:[{title:`How to Compare JSON`,steps:[`Paste or import the left and right inputs.`,`Choose Auto-detect or select the input format for each side.`,`Review the summary and the change list, then copy or download the diff.`]},{title:`What the Diff Shows`,paragraphs:[`Objects are compared structurally, so key order does not create differences. Arrays are compared by index. Added, removed and changed values are shown with their JSONPath.`,`A changed value displays its before and after values. Large differences are limited and marked as truncated.`]},{title:`Input Formats and Limits`,paragraphs:[`Each side can use JSON, YAML, XML, CSV, TSV or JSONL. CSV and XML conversions may be lossy, so compare the parsed JSON structures rather than the original source text.`,`The comparison runs locally. Very large inputs require clicking Compare instead of waiting for automatic comparison.`]}],faqs:[{question:`Does JSON key order matter?`,answer:`No. Objects are compared structurally, so the same keys in a different order are considered equal.`},{question:`How are arrays compared?`,answer:`Arrays are compared by index. An item inserted at the beginning can therefore appear as many changes in the following positions.`},{question:`Is my JSON uploaded?`,answer:`No. Both inputs are parsed and compared in your browser.`}],references:[{href:`https://www.rfc-editor.org/rfc/rfc8259`,label:`RFC 8259: The JSON Data Interchange Format`},{href:`https://www.rfc-editor.org/rfc/rfc9535`,label:`RFC 9535: JSONPath`}]},jsonschema:{title:`Validate JSON with JSON Schema Online`,intro:`Check JSON data against a JSON Schema and review validation errors by instance path. Schemas and data are parsed and validated locally in your browser.`,sections:[{title:`How to Validate JSON`,steps:[`Paste or import a JSON Schema on the left and the JSON data on the right.`,`Keep Auto-detect or choose the input format; JSON, YAML, XML, CSV, TSV and JSONL are accepted for the instance.`,`Select Validate, or wait for the automatic check, then review each error path and keyword.`]},{title:`Supported Keywords`,paragraphs:[`Draft 2020-12 is supported, including type, required, properties, additionalProperties, items, prefixItems, enum, const, anyOf, oneOf, allOf and $ref. Formats such as date-time, email, uri, ipv4 and uuid are checked when present.`,`Most Draft-07 schemas also validate because unknown keywords are ignored. Keywords whose semantics changed between drafts, such as dependencies or exclusiveMinimum, may behave differently.`]},{title:`Reading Validation Errors`,paragraphs:[`Each error shows its JSONPath, the failing keyword and the schema location. Click the path to copy it, or copy the whole error list as JSON.`,`The on-screen list is capped to keep the page responsive; copying errors includes the full list.`]}],faqs:[{question:`Is my schema or data uploaded?`,answer:`No. Parsing and validation run in your browser with a bundled JSON Schema validator.`},{question:`Which JSON Schema drafts are supported?`,answer:`Draft 2020-12 is fully supported. Most Draft-07 schemas work as well, but draft-specific keyword semantics may differ.`},{question:`Why does an empty JSONPath appear?`,answer:`An empty path means the error applies to the whole instance, such as a missing required field or a disallowed extra property.`}],related:[{href:`/json/`,label:`JSON Formatter and JSONPath Query`},{href:`/jsondiff/`,label:`JSON Diff and Compare`}],references:[{href:`https://json-schema.org/draft/2020-12`,label:`JSON Schema Draft 2020-12`},{href:`https://ajv.js.org/`,label:`Ajv JSON Schema Validator`}]},hash:{title:`Calculate File and Text Hashes Online`,intro:`Compute MD5, SHA-1, SHA-256, SHA-512, CRC32 and HMAC for text or files. Files are read in chunks and hashed locally in your browser.`,sections:[{title:`Hash Text or a File`,steps:[`Choose Text or File and enter the text or drop a file.`,`Select one or more algorithms; MD5 and SHA-1 are marked as insecure for authentication.`,`For HMAC, choose the hash algorithm and enter the key as text or hex.`,`Select Calculate or recompute and copy, download or compare the result.`]},{title:`Supported Algorithms`,paragraphs:[`SHA-256 and SHA-512 are the usual choices for file integrity, while MD5 and SHA-1 remain useful for legacy compatibility and non-security checksums.`,`CRC32 is a fast error-detection checksum, not a cryptographic hash. The calculator uses the standard IEEE polynomial and shows eight hex digits.`,`HMAC combines a hash with a secret key and supports SHA-1, SHA-256 and SHA-512 here. Keys stay in memory and are never uploaded or stored.`]},{title:`Verify a Downloaded File`,paragraphs:[`Paste the checksum published by the vendor into the expected-hash field. The page normalizes spaces, prefixes such as SHA256: and letter case, then reports which algorithm matches.`,`Files are read with the browser file stream API, so multi-gigabyte files are hashed in chunks without being uploaded or loaded all at once.`]}],faqs:[{question:`Is my file uploaded?`,answer:`No. The file is read in chunks and hashed with a bundled WebAssembly implementation in your browser.`},{question:`Which hash should I use?`,answer:`Use SHA-256 or SHA-512 for integrity and signatures. Avoid MD5 and SHA-1 for new security work; CRC32 is only for error detection.`},{question:`Why does the CRC32 result look different from another tool?`,answer:`This page uses the standard IEEE 802.3 CRC32 polynomial and displays the checksum in uppercase hex. Tools that show a decimal value or a different polynomial will differ.`},{question:`Can I hash a very large file?`,answer:`Yes. Files are streamed in chunks, and you can cancel a running hash at any time. Available memory and disk speed determine the practical limit.`}],related:[{href:`/hexviewer/`,label:`Binary HEX Viewer`},{href:`/espbin/`,label:`ESP BIN Firmware Inspector`},{href:`/json/`,label:`JSON Formatter and Converter`}],references:[{href:`https://www.rfc-editor.org/rfc/rfc1321`,label:`RFC 1321: MD5 Message-Digest Algorithm`},{href:`https://www.rfc-editor.org/rfc/rfc4231`,label:`RFC 4231: HMAC Test Vectors`},{href:`https://csrc.nist.gov/publications/detail/fips/180/4/final`,label:`FIPS 180-4: Secure Hash Standard`}]},hexconv:{title:`Convert and Merge Intel HEX, SREC and BIN`,intro:`Convert Intel HEX and Motorola S-record files to raw BIN, generate HEX or SREC from BIN, merge images by address, fill gaps, crop ranges and export individual segments locally.`,sections:[{title:`Convert Firmware Formats`,steps:[`Paste HEX or SREC text, or drop .hex, .srec and .bin files.`,`Enter a base address before adding a BIN file; BIN has no address metadata.`,`Choose BIN, Intel HEX or Motorola SREC as the output and select Generate.`,`Download the result or copy the generated text.`]},{title:`Merge and Fill`,paragraphs:[`Files are merged by absolute address. The default policy rejects overlapping data; you can keep the first value or let later files overwrite it.`,`BIN output starts at the lowest address and fills gaps with the selected byte, 0xFF by default. Use the start and end fields to restrict the exported range.`]},{title:`Export Segments`,paragraphs:[`The merged image is split into continuous address ranges. Each row can be downloaded as BIN, HEX or SREC without changing the other segments.`,`Intel HEX and SREC output preserve gaps instead of inserting fill bytes; record length and address width can be adjusted for the target toolchain.`]}],faqs:[{question:`Why does a BIN file need a base address?`,answer:`A raw BIN file contains no address information. Provide the flash or memory address where the first byte belongs, such as 0x08000000.`},{question:`What happens when images overlap?`,answer:`By default the converter stops and reports the conflict. Keep-first or last-wins can resolve overlaps when you know which image is authoritative.`},{question:`Are file checksums verified?`,answer:`Yes. Every Intel HEX and S-record line is checked for a valid checksum and record length before conversion.`},{question:`How large can the output be?`,answer:`BIN output spans are capped at 64 MiB. Use the crop fields or segment export to avoid expanding large address gaps.`}],related:[{href:`/hexviewer/`,label:`Binary HEX Viewer`},{href:`/espbin/`,label:`ESP BIN Firmware Inspector`},{href:`/hash/`,label:`Hash and Checksum Calculator`}],references:[{href:`https://en.wikipedia.org/wiki/Intel_HEX`,label:`Intel HEX record format`},{href:`https://en.wikipedia.org/wiki/SREC_(file_format)`,label:`Motorola S-record format`}]},base64:{title:`Encode and Decode UTF-8 Text with Base64`,intro:`Convert text to standard Base64 or URL-safe Base64, and decode either form back to UTF-8 text. This is a text tool, not a binary file converter.`,sections:[{title:`How to Encode and Decode Base64`,steps:[`Enter plain text and select Encode for standard Base64, or URL Safe Encode for Base64URL.`,`To decode, paste the encoded text and select Decode or URL Safe Decode.`,`Copy the result, or swap input and output to check a round trip.`]},{title:`Text and Unicode Examples`,paragraphs:[`Text is converted to UTF-8 bytes before encoding. Chinese characters and emoji are supported. Standard encoding includes padding where needed; URL-safe encoding omits it.`],example:`Text: Hello
Base64: SGVsbG8=

Text: 你好
Base64: 5L2g5aW9

Text: 🚀
Standard Base64: 8J+agA==
URL-safe Base64: 8J-agA`},{title:`Standard Base64 and Base64URL`,paragraphs:[`Base64URL replaces + with - and / with _. Both decode buttons accept these URL-safe characters, remove whitespace, and restore missing padding when the length permits it.`,`A Base64 payload can contain arbitrary bytes, but this decoder requires valid UTF-8. Binary images, compressed files and text encoded in other character sets may fail to decode. Remove a data URL prefix such as data:text/plain;base64, before decoding its payload.`]},{title:`Base64 Is Encoding, Not Encryption`,paragraphs:[`Anyone with an encoded value can decode it without a password. Base64 provides neither confidentiality nor proof that data is authentic. Use an appropriate encryption scheme when confidentiality is required.`]}],faqs:[{question:`Why does Base64 decoding fail?`,answer:`The input may contain invalid characters, impossible padding or a truncated payload. Decoding also fails when the resulting bytes are not valid UTF-8. Removing whitespace cannot repair missing data.`},{question:`Can this tool decode a JWT?`,answer:`It can decode an individual Base64URL text segment, such as a JWT header or payload. Do not paste the entire dot-separated token. Decoding does not verify its signature or establish that its claims are trustworthy.`},{question:`Is Base64 the same as URL encoding?`,answer:`No. Base64 represents bytes using a text alphabet. Percent encoding escapes characters in URL components. Standard Base64 may require escaping when used in a URL; Base64URL uses a different alphabet.`},{question:`Where is conversion history stored?`,answer:`This page keeps up to ten conversions in memory. Reloading the page clears that history. Conversion runs locally; third-party analytics and advertising scripts also load on the website.`}],related:[u.json,u.aes],references:[{href:`https://www.rfc-editor.org/rfc/rfc4648`,label:`RFC 4648: Base64 and URL-safe encodings`}]},aes:{title:`How This AES-GCM Text Encryption Tool Works`,intro:`Encrypt UTF-8 text with the browser’s Web Crypto API and decrypt the JSON result using the same secret and key mode. AES-GCM provides authenticated encryption: modified ciphertext or mismatched parameters cause decryption to fail.`,sections:[{title:`How to Encrypt and Decrypt Text`,steps:[`Enter your text and secret. Choose SHA-256 or Raw key mode.`,`Keep automatic random IV enabled and select Encrypt.`,`Save the complete output JSON, including its iv and ciphertext fields. Keep your secret separately.`,`For decryption, paste that JSON into the input, enter the same secret, and manually select the original key mode before selecting Decrypt. The keyDerivation field does not automatically switch the interface’s mode.`]},{title:`Key Modes and IV Requirements`,paragraphs:[`SHA-256 mode hashes the UTF-8 secret once to obtain a 256-bit AES key. It does not use a salt or a deliberately slow password derivation function such as PBKDF2. A weak password remains vulnerable to guessing; this mode is not a password vault design.`,`Raw mode imports the UTF-8 bytes of the secret directly as an AES key. The secret must occupy exactly 16, 24 or 32 bytes, corresponding to AES-128, AES-192 or AES-256. It is not interpreted as hexadecimal or Base64, and non-ASCII characters may occupy multiple bytes.`,`Automatic mode generates a random 12-byte IV for each encryption. A manual IV must decode from Base64 to exactly 12 bytes. Never reuse an IV with the same key. The IV is not secret and is stored with the ciphertext.`]},{title:`Output Format and Compatibility`,paragraphs:[`The JSON contains algorithm (AES-GCM), keyDerivation (SHA-256 or Raw), iv (Base64) and ciphertext (Base64). Web Crypto appends the default 128-bit authentication tag to the encrypted bytes; this combined value is stored in ciphertext.`,`To decrypt elsewhere, use the same UTF-8 secret handling, key derivation, IV and 128-bit tag. No additional authenticated data (AAD) is supplied. Libraries that expect a separate tag must split the final 16 bytes from the decoded ciphertext. AES-CBC results and unrelated AES payload formats are not interchangeable with this JSON.`]},{title:`Round-Trip Example`,paragraphs:[`Encrypt the text Hello with a secret of your choice, SHA-256 mode and automatic IV. Move the entire JSON output back to the input, retain the secret and SHA-256 mode, and decrypt. The result should be Hello. Repeating encryption normally produces different JSON because the IV is random.`,`Web Crypto requires a secure context such as HTTPS or localhost. The encryption code processes text locally; the website also loads third-party analytics and advertising scripts.`]}],faqs:[{question:`Why does decryption fail with the right password?`,answer:`Check the selected key mode as well as the password. Preserve the complete JSON, IV and ciphertext. Changed bytes, a missing authentication tag, or a payload from another AES format can also cause failure.`},{question:`Can I recover a forgotten secret?`,answer:`The tool has no recovery mechanism and does not include the secret in the output JSON. Retain the secret and complete payload if you need to decrypt later.`},{question:`Can I encrypt files or supply AAD?`,answer:`This interface encrypts text and does not expose file encryption or additional authenticated data. Use a tool designed for those requirements.`}],related:[u.base64,u.json],references:[{href:`https://developer.mozilla.org/en-US/docs/Web/API/AesGcmParams`,label:`Web Crypto AES-GCM parameters and authentication tags`}]},serial:{title:`Web Serial Terminal: Connection Guide and Troubleshooting`,intro:`Connect to a serial device from your browser, inspect received bytes in HEX or an ANSI terminal, and send text or hexadecimal commands. Serial communication takes place on your computer without a local terminal server.`,sections:[{title:`Browser and Device Requirements`,paragraphs:[`Use a desktop browser with Web Serial enabled, such as Chrome or Edge, over HTTPS or localhost. Browser policies and operating-system permissions can restrict access. The page detects API availability; a browser name alone does not guarantee access.`,`Connect a device that exposes a serial port, using a data-capable USB cable. USB-to-serial adapters may require an operating-system driver. Close other serial monitors before opening the same port.`]},{title:`How to Connect a Serial Device`,steps:[`Connect the device and select its documented baud rate, data bits, stop bits and parity.`,`Select Connect and choose the correct port in the browser permission dialog.`,`Choose the terminal or HEX display and inspect incoming data.`,`Choose text or HEX sending, set the line ending required by the device, and send a known command.`,`Disconnect before opening the device in a firmware flasher or another terminal.`]},{title:`ASCII, HEX and Line Endings`,paragraphs:[`Text and HEX are different representations of bytes. For example, sending the byte 41 in HEX represents ASCII A; sending the text 41 sends the two characters 4 and 1. Binary protocols are usually easier to inspect in the HEX view.`,`A device may wait for LF, CR, or CRLF before processing a text command. Select the protocol’s expected ending instead of assuming Enter is sufficient. DTR and RTS can affect reset or boot mode on some boards; use them according to the board documentation.`]},{title:`Troubleshooting Serial Connections`,paragraphs:[`No port available: check the USB cable, system device list, adapter driver and browser permissions. A charge-only cable will not provide a data connection.`,`Port fails to open: close IDE serial monitors, other browser tabs and native terminal programs, then retry. Check operating-system access permissions.`,`Unreadable text: verify baud rate and framing parameters. Binary traffic is not necessarily readable text; inspect it in HEX.`,`No response: check the command bytes, line ending and device protocol. For UART adapters, verify TX/RX wiring, a common ground and compatible logic voltage using the device documentation.`]}],faqs:[{question:`Can this terminal flash ESP firmware?`,answer:`It sends and receives serial data but does not implement the ESP flashing workflow. Disconnect here and use the ESP Firmware Flasher for that task.`},{question:`Can two tools use the same serial port at once?`,answer:`An open serial port is normally exclusive. Disconnect the current tool before connecting with another tab, IDE or flasher.`},{question:`Is received serial data sent to a server?`,answer:`The terminal reads and writes the selected port locally. Its communication code does not forward terminal data to a processing server. The website also loads analytics and advertising scripts.`}],related:[u.espflash,u.jlink],references:[{href:`https://developer.chrome.com/docs/capabilities/serial`,label:`Chrome Developers: Read from and write to a serial port`}]},jlink:{title:`Web J-Link Flasher: Requirements and Firmware Guide`,intro:`Use WebUSB and SWD to connect a J-Link probe and load BIN or Intel HEX firmware. This browser workflow does not require a local flashing server, but USB driver configuration may still be needed.`,sections:[{title:`Requirements and Compatibility Limits`,paragraphs:[`Use a desktop browser that exposes WebUSB over HTTPS or localhost. Connect the probe to the target’s SWDIO, SWCLK, ground and voltage-reference connections according to the probe and board documentation. Confirm target power and voltage compatibility.`,`The selector includes STM32F103, STM32F401/F411, nRF52832 and nRF52840 presets. A listed preset is not evidence of a hardware-tested configuration. In the current implementation, erase and programming branches exist for STM32F1 and nRF52; STM32F4 flash operations are not implemented. Do not use the STM32F401/F411 presets for flashing.`,`No physical board/probe validation matrix is published here. Compatibility depends on the probe, target and system; use the chip vendor’s supported programming tool where this implementation does not cover your configuration.`]},{title:`How to Prepare a Flashing Session`,steps:[`Confirm the supported target family, firmware and SWD wiring before connecting.`,`Close J-Link Commander, Keil, Ozone and other software that may own the probe.`,`Connect in the browser and select the matching target preset.`,`Load a HEX or BIN file and inspect every displayed segment address. Select the target before loading a BIN; reload the BIN if the target changes.`,`Only start the erase-and-flash operation when the addresses and target match. This workflow performs a mass erase before writing and then requests a target reset.`]},{title:`BIN and Intel HEX Address Handling`,paragraphs:[`Intel HEX records include addresses; the tool parses them into segments. A BIN file has no embedded load address. This interface places it at the selected preset’s flash base: 0x08000000 for the listed STM32 presets or 0x00000000 for the listed nRF52 presets.`,`There is no arbitrary BIN offset field in this interface. If your application belongs after a bootloader or at another address, do not flash that BIN at the preset base. Use an appropriately addressed HEX file or a programmer with explicit address control. Mass erase may remove existing application data and bootloader contents; this interface has no backup workflow.`]},{title:`USB Driver and Connection Troubleshooting`,paragraphs:[`An interface-claim error can mean the probe is in use or its current driver prevents WebUSB access. Close other tools first. On Windows, some configurations require binding the intended J-Link interface to WinUSB.`,`Changing an interface driver can affect native SEGGER tools. Confirm the correct interface and how to restore its original driver before changing it. Driver changes are not required on every system.`,`If USB connects but SWD does not, check target power, reference voltage, wiring and target protection settings. A completed browser progress bar does not substitute for independent firmware verification.`]}],faqs:[{question:`Does this support every STM32 or nRF52 device?`,answer:`No. The presets and implemented flash branches define a limited scope. In particular, the listed STM32F4 presets currently lack erase/program implementations. No universal device or probe compatibility is claimed.`},{question:`Does flashing preserve existing firmware and settings?`,answer:`The workflow invokes mass erase before programming. Do not rely on it to preserve an existing application, bootloader or settings in erased flash.`},{question:`Can I flash an ESP32 with J-Link here?`,answer:`This page’s presets do not implement ESP flashing. Use the ESP Firmware Flasher for compatible serial download workflows.`}],related:[u.serial,u.espflash],references:[{href:`https://developer.chrome.com/docs/capabilities/usb`,label:`Chrome Developers: Access USB devices on the web`}]},espflash:{title:`Flash ESP Firmware from Your Browser`,intro:`Connect an Espressif device through Web Serial and write one or more BIN files using esptool-js. Each file is paired with its flash offset; the correct files and offsets come from your firmware build or release instructions.`,sections:[{title:`Browser, Board and Firmware Requirements`,paragraphs:[`Use a desktop browser with Web Serial enabled, such as Chrome or Edge, over HTTPS or localhost. Your board must expose a compatible serial download connection. A data USB cable and, for some adapters, a system USB-to-serial driver are required.`,`The esptool-js dependency includes loaders for ESP8266 and ESP32 variants such as ESP32-S2, S3, C3 and C6. Library support is not a guarantee that a particular board, USB connection or security configuration has been tested with this page. Confirm the detected chip and your firmware’s intended target.`]},{title:`How to Flash ESP Firmware`,steps:[`Close other serial monitors, connect the board and select a suitable connection speed.`,`Select Connect and choose the board’s serial port. Check the detected chip information.`,`Add each BIN file and enter its documented starting offset. Check the complete file-and-address list.`,`Decide whether a full erase is required by the firmware instructions; leave it disabled when it is not needed.`,`Start flashing and wait for completion. Reset the board if necessary, then disconnect before opening the Web Serial Terminal.`]},{title:`Firmware Files and Flash Offsets`,paragraphs:[`Separate bootloader, partition-table and application files may each need different offsets. A merged image has its own documented starting offset. Do not treat the prefilled addresses as a universal recipe.`,`Use the flashing command, manifest or release instructions supplied with the exact firmware build. Enter offsets in hexadecimal with a 0x prefix, or in decimal. Ensure files do not overlap and fit the target’s flash layout.`,`Full erase removes flash contents, which can include firmware, stored credentials, settings and filesystem data. This interface does not create a backup before erasing.`]},{title:`Connection and Boot Troubleshooting`,paragraphs:[`No port or failure to open: check the data cable, system driver and permissions, and close other programs using the port.`,`Failed handshake: follow your board’s download-mode instructions. On many ESP32 development boards, holding BOOT while pressing and releasing EN/RESET enters download mode; button behavior varies by board and chip.`,`Interrupted writes: try a lower speed, a shorter cable and a stable power supply. Confirm that no other application is accessing the board.`,`Flash completes but the application does not boot: verify chip compatibility, the complete set of files, their offsets and the partition layout. Follow the board’s instructions to leave download mode. Secure boot or flash encryption may require a different, project-specific workflow.`]}],faqs:[{question:`Where do I find the correct flash offsets?`,answer:`Use the build output’s flashing command, firmware manifest or release documentation. Offsets depend on the chip and project layout; the application offset alone is not a complete flashing plan.`},{question:`Do I always need to hold BOOT?`,answer:`No. Many boards support automatic reset into download mode. If that fails, use the manual sequence documented for your exact board.`},{question:`Can I upload HEX or ELF firmware?`,answer:`This interface accepts BIN files. Obtain the BIN images and their offsets from the project’s build or release process.`},{question:`Are firmware files uploaded to a server?`,answer:`The flashing code reads files locally and sends their bytes to the selected serial device. It does not upload them to a flashing server. The website also loads third-party analytics and advertising scripts.`}],related:[u.serial,u.jlink,u.espbin],references:[{href:`https://docs.espressif.com/projects/esptool/en/latest/esp32/esptool/flashing-firmware.html`,label:`Espressif: Flashing firmware and file offsets`},{href:`https://docs.espressif.com/projects/esptool/en/latest/esp32/advanced-topics/boot-mode-selection.html`,label:`Espressif: ESP32 boot mode selection`}]},espbin:{title:`Inspect ESP BIN Firmware Locally`,intro:`Open an ESP .bin firmware file in your browser and inspect image headers, application metadata, partition tables, checksums, SHA-256 and a paged HEX preview. The file is parsed locally and is not uploaded.`,sections:[{title:`How to Inspect a BIN File`,steps:[`Choose or drop an ESP .bin firmware file.`,`Review the detected file type, SHA-256, image count and partition table count.`,`Switch between Summary and Structure to inspect app metadata, segments and partitions.`,`Use the HEX preview pager to inspect raw bytes without loading the whole file into a single text area.`,`Copy the summary when you need to share the detected metadata.`]},{title:`What This Inspector Can Identify`,paragraphs:[`The parser detects ESP image headers, image segments, application descriptors and partition tables where they follow supported Espressif binary layouts.`,`For merged firmware, the scanner checks sector-aligned structures and reports confirmed images or partition tables. Detection is a convenience aid, not proof that the firmware is complete or suitable for a board.`]},{title:`Offsets and Flashing Use`,paragraphs:[`The optional starting offset is only used as a display reference. It does not modify the file and does not create a flashing plan.`,`Partition offsets are absolute flash addresses. Do not add the current display offset to partition entries. For actual flashing, use the build output, manifest or vendor instructions for the exact firmware package.`]},{title:`Privacy and Limits`,paragraphs:[`Parsing runs in the browser with a Web Worker. Firmware bytes are not uploaded by the inspector. The website may still load analytics scripts.`,`Large files may be limited to HEX preview or partial structure scanning to keep the page responsive. Unsupported or encrypted contents may appear as unknown data.`]}],faqs:[{question:`Can this prove a firmware file is safe or authentic?`,answer:`No. It displays parseable metadata and checksums. It does not verify trust, signatures, source authenticity or board compatibility.`},{question:`Can I edit or repack firmware here?`,answer:`No. The inspector is read-only and does not modify or generate BIN files.`},{question:`Does this replace the ESP Firmware Flasher?`,answer:`No. Use this page to inspect files, then use the ESP Firmware Flasher when you need to connect a board and write firmware.`}],related:[u.espflash,u.serial],references:[{href:`https://docs.espressif.com/projects/esptool/en/latest/esp32/esptool/image-format.html`,label:`Espressif: Firmware image format`}]},imgconv:{title:`Convert PNG, JPEG and WebP Images in Your Browser`,intro:`Load a PNG, JPEG or WebP image, choose the output format, resize it, adjust lossy quality and optionally produce Base64 text. Decoding, canvas rendering and encoding happen locally; the image is not uploaded.`,sections:[{title:`How to Convert an Image`,steps:[`Drop or choose a PNG, JPEG or WebP file, or paste an image from the clipboard.`,`Choose PNG, JPEG or WebP as the output format.`,`Select a resize mode and enter a percentage, width or height when needed.`,`Adjust quality for JPEG or WebP, and choose a background when transparency must be flattened.`,`Select Convert Image, review the preview and file size, then download it or copy the Base64 output.`]},{title:`Choosing an Output Format`,paragraphs:[`PNG is lossless and keeps an alpha channel, which suits icons, screenshots and images that need transparency. JPEG is lossy and widely compatible; it has no alpha channel, so transparent areas are filled with the selected background. WebP can be lossy or effectively lossless depending on the quality setting and usually produces a smaller file than JPEG or PNG at a similar appearance.`,`Re-encoding always creates a new file. Converting a heavily compressed JPEG to PNG does not restore lost detail, and it usually makes the file much larger. Converting a PNG with transparency to JPEG requires filling the background.`]},{title:`Resizing and Quality`,paragraphs:[`Original keeps the decoded dimensions. Percent scales both axes by the same factor. Fixed width or fixed height preserves the aspect ratio and calculates the other side automatically. The page reports the target dimensions before conversion.`,`For JPEG and WebP, lower quality values reduce file size and remove more detail. PNG ignores the quality setting because it is lossless. Output is limited to 16 million pixels to stay within common browser canvas limits.`]},{title:`Base64 and Data URLs`,paragraphs:[`Base64 encodes the converted bytes as text. A Data URL prefixes the Base64 payload with its MIME type, such as data:image/webp;base64,..., so it can be used directly in an img src or CSS url(). Raw Base64 omits that prefix.`,`Base64 is encoding, not compression: the text is about 1.33 times the size of the binary image. Very large images also produce very large text strings, which can be cumbersome to edit or paste.`]}],faqs:[{question:`Are my images uploaded?`,answer:`No. The page decodes and encodes images with browser APIs and does not send them to a processing server. The website still loads third-party analytics and advertising scripts.`},{question:`Why does JPEG turn transparency white?`,answer:`JPEG has no alpha channel. Transparent areas are composited onto the selected background, which defaults to white. Use PNG or WebP when transparency must be preserved.`},{question:`Why is the new file larger than the original?`,answer:`The original may already be heavily compressed, the output quality may be high, or the output dimensions may be larger. Try a lower quality, smaller dimensions, or a different format.`},{question:`Does converting to PNG improve quality?`,answer:`No. PNG preserves the pixels it receives, but it cannot restore detail that a previous lossy encoding removed. Start from the highest-quality source available.`}],related:[{href:`/svgtopng/`,label:`SVG to PNG Converter`},{href:`/ico/`,label:`SVG to ICO Converter`},{href:`/base64/`,label:`Base64 Encoder and Decoder`}],references:[{href:`https://developer.mozilla.org/en-US/docs/Web/API/HTMLCanvasElement/toBlob`,label:`MDN: HTMLCanvasElement.toBlob()`},{href:`https://www.rfc-editor.org/rfc/rfc4648`,label:`RFC 4648: Base64 encoding`}]},logplot:{title:`Plot Curves from Serial Logs, CSV, TSV or JSON`,intro:`Paste plain-text serial output, a delimited table or JSON. The page detects the likely X axis and numeric data columns, then draws a line chart as you type. Parsing and drawing happen locally in your browser.`,sections:[{title:`How to Plot Your Data`,steps:[`Paste serial logs, CSV/TSV rows or JSON into the input area, or load one of the samples.`,`The page detects the format, treats the first row as a header when it is not numeric, and builds a table of columns.`,`A time-like or increasing numeric column becomes the X axis; other numeric columns with changing values become curves.`,`Use the "Data columns" chips to show or hide curves, and the "X axis" dropdown to switch axes.`,`Drag across the chart to zoom, double-click to reset, then export PNG or CSV when needed.`]},{title:`Supported Input Formats`,paragraphs:[`Key-value logs: one or more key: value or key=value pairs per line. Records start at a time field; fields written before the time field, such as sys clock, are attached to the following record.`,`Delimited text: comma, tab, semicolon or pipe, with or without a header row. Quoted cells are supported.`,`JSON: an array of objects, arrays of rows, column arrays, or newline-delimited JSON objects. Nested objects are flattened with dot notation.`],example:`time,temperature(C),humidity(%)
2026-08-28T11:17:59Z,25.1,48
2026-08-28T11:18:00Z,25.4,47`},{title:`Automatic Detection Rules`,paragraphs:[`A column is treated as time when most values parse as a date-time, time-of-day or epoch timestamp in seconds, milliseconds or nanoseconds.`,`If no time column exists, the first increasing numeric column such as a clock or step counter is used, otherwise the row index becomes the X axis.`,`Numeric columns with changing values are plotted by default. Constant columns and monotonic counters are left unchecked but can be enabled.`],example:`sys clock:19481 status:2
current time: 2026/08/28 11:17:59
sample voltage: 3126 mV`},{title:`Units and Limits`,paragraphs:[`Units are read from headers such as temperature(C) or from values such as 3126 mV. They are labels only; values are not converted between units.`,`All curves share one Y axis. Log times without a time zone are treated as UTC. A time-of-day axis cannot detect midnight rollover, so backwards points are skipped and reported.`]},{title:`Privacy`,paragraphs:[`The paste is never uploaded; it is kept in local storage so a refresh does not lose it. The website may still load analytics scripts.`]}],faqs:[{question:`Why is my chart empty?`,answer:`No numeric columns were detected, or the X axis has no valid values. Check that the data has at least one numeric column and a recognizable time or counter column.`},{question:`Can I plot other fields such as current?`,answer:`Yes. Any numeric column can be toggled as a curve, and a time-like or increasing column can be selected as the X axis.`},{question:`Can it read the serial port directly?`,answer:`Not yet. Copy the output from a terminal such as the Web Serial Terminal and paste it here.`}],related:[u.serial,u.espflash]}},f=[`aria-label`],p={key:0},m={key:1},h={"aria-label":`Related tools`},g=[`href`],_={key:0},v=[`href`],y=o({__name:`ToolGuide`,props:{page:{type:String,required:!0}},setup(o){return(u,y)=>i(a)===`en`&&i(d)[o.page]?(t(),c(`article`,{key:0,class:`tool-guide`,lang:`en`,"aria-label":i(d)[o.page].title},[l(`h2`,null,r(i(d)[o.page].title),1),l(`p`,null,r(i(d)[o.page].intro),1),(t(!0),c(s,null,n(i(d)[o.page].sections,i=>(t(),c(`section`,{key:i.title},[l(`h3`,null,r(i.title),1),(t(!0),c(s,null,n(i.paragraphs,e=>(t(),c(`p`,{key:e},r(e),1))),128)),i.steps?(t(),c(`ol`,p,[(t(!0),c(s,null,n(i.steps,e=>(t(),c(`li`,{key:e},r(e),1))),128))])):e(``,!0),i.example?(t(),c(`pre`,m,[l(`code`,null,r(i.example),1)])):e(``,!0)]))),128)),l(`section`,null,[y[0]||(y[0]=l(`h3`,null,`Frequently Asked Questions`,-1)),(t(!0),c(s,null,n(i(d)[o.page].faqs,e=>(t(),c(`div`,{key:e.question,class:`guide-answer`},[l(`h4`,null,r(e.question),1),l(`p`,null,r(e.answer),1)]))),128))]),l(`nav`,h,[y[1]||(y[1]=l(`h3`,null,`Related Tools`,-1)),l(`ul`,null,[(t(!0),c(s,null,n(i(d)[o.page].related,e=>(t(),c(`li`,{key:e.href},[l(`a`,{href:e.href},r(e.label),9,g)]))),128))])]),i(d)[o.page].references?(t(),c(`section`,_,[y[2]||(y[2]=l(`h3`,null,`Technical References`,-1)),l(`ul`,null,[(t(!0),c(s,null,n(i(d)[o.page].references,e=>(t(),c(`li`,{key:e.href},[l(`a`,{href:e.href},r(e.label),9,v)]))),128))])])):e(``,!0)],8,f)):e(``,!0)}},[[`__scopeId`,`data-v-5257ad5b`]]);export{y as t};